-- Lead Desk · Sales see the leads they generated (10 Nov 2026)
-- Run once in Supabase → SQL Editor, after 22_generators.sql. Safe to run again. No leads are changed.
--
-- A sales engineer can now READ (not edit) a lead they generated themselves even when another engineer has it,
-- for their "Generated by me" tab. New permission lead.view_generated, on for Sales; the Supervisor can switch it
-- off in Users → Roles & permissions. Editing still needs the lead to be assigned to them (leads_update unchanged).

-- 1. Sales get the permission the first time this runs (later choices by the Supervisor stand)
update public.docs
set doc = jsonb_set(doc, '{roles,sales}',
      (select coalesce(jsonb_agg(distinct x), '[]'::jsonb)
         from jsonb_array_elements_text(coalesce(doc->'roles'->'sales','[]'::jsonb) || '["lead.view_generated"]'::jsonb) x))
where path = 'config/permissions' and doc ? 'roles'
  and not (coalesce(doc->'known','[]'::jsonb) ? 'lead.view_generated');

update public.docs
set doc = jsonb_set(doc, '{known}', (select coalesce(jsonb_agg(distinct x), '[]'::jsonb)
         from jsonb_array_elements_text(coalesce(doc->'known','[]'::jsonb) || '["lead.view_generated"]'::jsonb) x))
where path = 'config/permissions' and doc ? 'roles' and doc ? 'known';

-- 2. Who can read which lead (same as before, plus the generated-by rule)
drop policy if exists leads_select on public.leads;
create policy leads_select on public.leads for select to authenticated
  using (
    (select public.has_perm('lead.view_all'))
    or ((doc->>'deleted') is null and (select public.my_engineer()) <> '' and lower(coalesce(assigned_to,'')) = lower((select public.my_engineer())))
    or ((doc->>'deleted') is null and (select public.my_engineer()) <> '' and (select public.has_perm('lead.view_generated'))
        and lower(btrim(coalesce(doc->>'generatedBy',''))) = lower((select public.my_engineer())))
  );

-- Check: how many leads each engineer generated
select doc->>'generatedBy' as generated_by, count(*) from public.leads
where doc->>'generatedBy' in (select engineer from public.members where engineer is not null)
group by 1 order by 2 desc;
